A farm record system in Bindura uses this Python program.

```python
class Animal:
    def __init__(self, name):
        self.__name = name

    def describe(self):
        return self.__name + " is an animal"

    def produce(self):
        return 0

class Cow(Animal):
    def __init__(self, name, litres):
        super().__init__(name)
        self.__litres = litres

    def describe(self):
        return super().describe() + " that gives milk"

    def produce(self):
        return self.__litres

class Hen(Animal):
    def __init__(self, name, eggs):
        super().__init__(name)
        self.__eggs = eggs

    def produce(self):
        return self.__eggs

farm = [Cow("Mbuya", 12), Hen("Pepe", 3), Animal("Rex")]
total = 0
for a in farm:
    print(a.describe())
    total = total + a.produce()
print(total)
```
